@@ -532,16 +531,8 @@ func workingTreeMatchesCommit(worktreeRoot, filePath string, commitHash plumbing
 	if commitHash.Size() == config.SHA256.Size() {
 		of = config.SHA256
 	}
-	// Normalize CRLF→LF for text files: on Windows, agents (Node.js) may write
-	// files with CRLF, but git stores blobs with LF after autocrlf normalization.
-	// Hashing raw CRLF bytes would never match the LF blob hash. Binary files
-	// (containing null bytes) are left unchanged.
-	contentToHash := diskContent
-	if !bytes.Contains(diskContent, []byte{0}) {
-		contentToHash = bytes.ReplaceAll(diskContent, []byte("\r\n"), []byte("\n"))
-	}
