}

// FileChanges holds categorized file changes from git status.
type FileChanges struct {
	Modified []string // Modified or staged files
	New      []string // Untracked files (filtered if previouslyUntracked provided)
	Deleted  []string // Deleted files (staged or unstaged)
}

// DetectFileChanges returns categorized file changes from the current git status.
//
// previouslyUntracked controls new-file detection:
//   - nil: all untracked files go into New
//   - non-nil: only untracked files NOT in the pre-existing set go into New
//
// Modified includes both worktree and staging modified/added files.
// Deleted includes both staged and unstaged deletions.
// All results exclude .entire/ directory.
func DetectFileChanges(ctx context.Context, previouslyUntracked []string) (*FileChanges, error) {
	repoRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		return nil, fmt.Errorf("failed to get worktree root: %w", err)
	}

	// Use git CLI instead of go-git to avoid holding .git/index open.
	// On Windows, go-git's mandatory file locks can block subsequent git CLI
	// calls in the same process (e.g., filterToUncommittedFiles).
	cmd := exec.CommandContext(ctx, "git", "status", "--porcelain", "-uall")
	cmd.Dir = repoRoot
	out, err := cmd.Output()
	if err != nil {
		return nil, fmt.Errorf("failed to run git status: %w", err)
	}

	// Build set of pre-existing untracked files for quick lookup
	var preExisting map[string]bool
	if previouslyUntracked != nil {
		preExisting = make(map[string]bool, len(previouslyUntracked))
		for _, f := range previouslyUntracked {
			preExisting[f] = true
		}
	}

	var changes FileChanges
	for _, line := range strings.Split(string(out), "\n") {
		if len(line) < 4 {
			continue
		}
		x, y := line[0], line[1]
		file := filepath.ToSlash(line[3:])

		// Handle renames: "R  old -> new"
		if idx := strings.Index(file, " -> "); idx >= 0 {
			file = file[idx+4:]
		}

		if paths.IsInfrastructurePath(file) {
			continue
		}

		switch {
		case x == '?' && y == '?': // untracked
			if preExisting != nil {
				if !preExisting[file] {
					changes.New = append(changes.New, file)
				}
			} else {
				changes.New = append(changes.New, file)
			}
		case x == 'D' || y == 'D': // deleted
			changes.Deleted = append(changes.Deleted, file)
		default: // M, A, R, C in either index or worktree column
			changes.Modified = append(changes.Modified, file)
		}
	}

	return &changes, nil
}

// filterToUncommittedFiles removes files from the list that are already committed to HEAD
// with matching content. This prevents re-adding files that an agent committed mid-turn
// (already condensed by PostCommit) back to FilesTouched via SaveStep. Files not in
// HEAD or with different content in the working tree are kept. Fails open: if git
// errors (e.g. bare repo, no HEAD), returns the original list unchanged.
//
// Uses the git CLI instead of go-git to avoid index lock contention on Windows and
// to ensure consistent autocrlf/eol handling (git CLI respects system-level config,
// while go-git's content comparison would need manual CRLF normalization).
func filterToUncommittedFiles(ctx context.Context, files []string, repoRoot string) []string {
	if len(files) == 0 {
		return files
	}

	// git diff --name-only HEAD -- <files> prints only files that differ from HEAD.
	// Empty output means all files match HEAD (already committed). Exit 0 on success,
	// non-zero (128) only on fatal errors (no HEAD, not a repo, etc.).
	args := append([]string{"diff", "--name-only", "HEAD", "--"}, files...)
	cmd := exec.CommandContext(ctx, "git", args...)
	cmd.Dir = repoRoot
	out, err := cmd.Output()
	if err != nil {
		// Fail open: no HEAD (empty repo, initial commit), not a git repo, etc.
		logging.Warn(ctx, "filterToUncommittedFiles: git diff failed, keeping all files as uncommitted",
			slog.String("error", err.Error()))
		return files
	}

	trimmed := strings.TrimRight(string(out), "\n")
	if trimmed == "" {
		return nil // all files are committed with matching content
	}

	// Build a set of files that actually differ from HEAD.
	diffSet := make(map[string]bool)
	for _, line := range strings.Split(trimmed, "\n") {
		if line != "" {
			diffSet[filepath.ToSlash(line)] = true
		}
	}

	var result []string
	for _, f := range files {
		if diffSet[f] {
			result = append(result, f)
		}
	}
	return result
}

// FilterAndNormalizePaths converts absolute paths to relative and filters out
// infrastructure paths and paths outside the repo.
func FilterAndNormalizePaths(files []string, cwd string) []string {
	var result []string
	for _, file := range files {
		relPath := paths.ToRelativePath(file, cwd)
		if relPath == "" {
			continue // outside repo
		}
		if paths.IsInfrastructurePath(relPath) {
			continue // skip .entire directory
		}
		result = append(result, filepath.ToSlash(relPath))
	}
	return result
}

// mergeUnique appends elements from extra into base, skipping duplicates already in base.
func mergeUnique(base, extra []string) []string {
	if len(extra) == 0 {
		return base
	}
	seen := make(map[string]bool, len(base))
	for _, s := range base {
		seen[s] = true
	}
	for _, s := range extra {
		if !seen[s] {
			seen[s] = true
			base = append(base, s)
		}
	}
	return base
}

// resolveTmpDir returns the absolute path to the .entire/tmp directory,
